const body = $input.first().json.body;
const alerts = body.alerts || [];
const lines = alerts.map(a => {
  const l = a.labels || {};
  const ann = a.annotations || {};
  const state = a.status === 'resolved' ? 'RESOLVED' : (l.severity || 'firing').toUpperCase();
  return `[${state}] ${ann.summary || l.alertname}${ann.description ? '\n  ' + ann.description : ''}`;
});
const severity = alerts.some(a => a.status === 'firing' && (a.labels || {}).severity === 'critical') ? 'critical' : 'warning';
return [{ json: {
  title: `AI cost: ${body.status} (${alerts.length})`,
  message: lines.join('\n'),
  severity,
  status: body.status,
} }];
